import Image from 'next/image';

export default function WhyChoose() {
  const features = [
    {
      title: "Background Verified and Trusted Experts",
      icon: "https://snabbit.com/assets/what-makes-snabbit/trusted-experts.png"
    },
    {
      title: "Professionally Trained For Home Cleaning",
      icon: "https://snabbit.com/assets/what-makes-snabbit/flexible-booking.svg"
    },
    {
      title: "Freedom to Cancel or Reschedule",
      icon: "https://snabbit.com/assets/what-makes-snabbit/reschedule-or-cancel.svg"
    },
    {
      title: "Powered By Strong Women Workforce",
      icon: "https://snabbit.com/assets/what-makes-snabbit/maid.png"
    },
    {
      title: "Quality You Can Trust",
      icon: "https://snabbit.com/assets/what-makes-snabbit/rating.svg"
    }
  ];

  return (
    <section id="why-us" className="py-20 bg-white">
      <div className="container mx-auto px-4">
        <h2 className="text-3xl font-bold text-center mb-12">WHY CHOOSE SNABBIT</h2>
        <div className="grid grid-cols-1 md:grid-cols-3 lg:grid-cols-5 gap-8">
          {features.map((feature, index) => (
            <div key={index} className="text-center">
              <Image src={feature.icon} alt={feature.title} width={80} height={80} className="mx-auto mb-4" />
              <h3 className="text-lg font-semibold">{feature.title}</h3>
            </div>
          ))}
        </div>
        <div className="text-center mt-12">
          <h3 className="text-2xl font-bold">Trusted By 6000+ Families</h3>
        </div>
      </div>
    </section>
  );
}