export default function FAQs() {
  const faqs = [
    "What is Snabbit?",
    "How do I book a service with Snabbit?",
    "Can we get multiple tasks done in one booking?",
    "How can I trust the Experts sent by Snabbit?",
    "What if I need to cancel or reschedule my booking?",
    "I want to report an issue with the service",
    "How quickly can I get an Expert to my home?",
    "Do you offer regular or subscription-based services?"
  ];

  return (
    <section id="faqs" className="py-20 bg-white">
      <div className="container mx-auto px-4">
        <h2 className="text-3xl font-bold text-center mb-12">FAQs</h2>
        <div className="max-w-2xl mx-auto">
          {faqs.map((faq, index) => (
            <div key={index} className="border-b border-gray-200 py-4">
              <h3 className="text-lg font-semibold cursor-pointer hover:text-orange-500">{faq}</h3>
            </div>
          ))}
        </div>
      </div>
    </section>
  );
}