import Image from 'next/image';

export default function Header() {
  return (
    <header className="bg-white shadow-md">
      <div className="container mx-auto px-4 py-4 flex justify-between items-center">
        <div className="flex items-center">
          <Image
            src="https://snabbit.com/assets/snabbit-icon.svg"
            alt="Snabbit Logo"
            width={40}
            height={40}
            className="mr-2"
          />
          <span className="text-2xl font-bold text-gray-800">Snabbit</span>
        </div>
        <nav className="hidden md:flex space-x-6">
          <a href="#services" className="text-gray-600 hover:text-gray-800">Services</a>
          <a href="#how-it-works" className="text-gray-600 hover:text-gray-800">How it works</a>
          <a href="#why-us" className="text-gray-600 hover:text-gray-800">Why us?</a>
          <a href="#faqs" className="text-gray-600 hover:text-gray-800">FAQs</a>
        </nav>
        <button className="bg-orange-500 text-white px-4 py-2 rounded-lg hover:bg-orange-600">
          Download App
        </button>
      </div>
    </header>
  );
}